void tick_screen_empty_room() {
}

typedef void (*tick_screen_func_t)();
tick_screen_func_t tick_screen_funcs[] = {
    tick_screen_main,
    tick_screen_living,
    tick_screen_master,
    tick_screen_kitchen,
    tick_screen_bath,
    tick_screen_detail_light,
    tick_screen_detail_ac,
    tick_screen_detail_curtain,
    tick_screen_detail_sensor,
    tick_screen_detail_camera,
    tick_screen_detail_plug,
    tick_screen_notify,
    tick_screen_energy,
    tick_screen_settings,
    tick_screen_wifi,
    tick_screen_devices,
    tick_screen_security,
    tick_screen_scene_detail,
    tick_screen_add_type,
    tick_screen_add_pairing,
    tick_screen_add_done,
    tick_screen_about,
    tick_screen_offline,
    tick_screen_empty_room,
};
void tick_screen(int screen_index) {
    if (screen_index >= 0 && screen_index < 24) {
        tick_screen_funcs[screen_index]();
    }
}
void tick_screen_by_id(enum ScreensEnum screenId) {
    tick_screen(screenId - 1);
}

