void create_screens() {

// Set default LVGL theme
    lv_display_t *dispp = lv_display_get_default();
    lv_theme_t *theme = lv_theme_default_init(dispp, lv_palette_main(LV_PALETTE_BLUE), lv_palette_main(LV_PALETTE_RED), true, LV_FONT_DEFAULT);
    lv_display_set_theme(dispp, theme);
    
    // Initialize screens
    // Create screens
    create_screen_main();
    create_screen_living();
    create_screen_master();
    create_screen_kitchen();
    create_screen_bath();
    create_screen_detail_light();
    create_screen_detail_ac();
    create_screen_detail_curtain();
    create_screen_detail_sensor();
    create_screen_detail_camera();
    create_screen_detail_plug();
    create_screen_notify();
    create_screen_energy();
    create_screen_settings();
    create_screen_wifi();
    create_screen_devices();
    create_screen_security();
    create_screen_scene_detail();
    create_screen_add_type();
    create_screen_add_pairing();
    create_screen_add_done();
    create_screen_about();
    create_screen_offline();
    create_screen_empty_room();
}